import {INSTRUMENT,CONSENT,QUESTIONS,PREVIOUS_QUESTIONS,DIMENSIONS,GROUPS,questionIds,reflect,summaryOf,describeProfile,levelOf,layersOf,roleLayers,validAnswers,normalizeLabel,organizeTags,encodeProfile,decodeProfile,compareProfiles,comparisonInputs} from './reflection.mjs';
const SITEKEY='0x4AAAAAAFaMaq3Xy2r-CpoC';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phrase=s=>String(s).split(/(?<=[、。])/u).filter(Boolean).map(t=>`<span class="phrase">${esc(t)}</span>`).join('');
const PREVIOUS_KEY='heki16_reflection_v1',KEY='heki16_reflection_v2',RECEIPT='heki16_research_receipt_v1';
const empty=()=>({version:2,instrument:INSTRUMENT,answers:Array(32).fill(null),mode:32,index:0,complete:false,tags:[],learned:{},adult:false});
let state=empty(),sample=false,shared=null,undoTags=null,toastTimer,receipt=null,compareCode='',pendingPartnerCode='';
try{const saved=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(PREVIOUS_KEY)),instrument=saved?.instrument||'reflection-1';if(saved&&['reflection-1',INSTRUMENT].includes(instrument)&&validAnswers(saved.answers,saved.mode,instrument)&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<saved.mode){state={...empty(),...saved,instrument,tags:organizeTags(Array.isArray(saved.tags)?saved.tags:[]),learned:saved.learned&&typeof saved.learned==='object'?saved.learned:{}};}receipt=JSON.parse(localStorage.getItem(RECEIPT));}catch{}
const persist=()=>{if(sample||shared)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{$('#storage-warning').hidden=false;}};
const say=text=>{clearTimeout(toastTimer);$('#status').textContent=text;toastTimer=setTimeout(()=>$('#status').textContent='',4500);};
let activeWidget=null;
const close=()=>{if(activeWidget!==null&&window.turnstile){window.turnstile.remove(activeWidget);activeWidget=null;}$('#modal').close();};
$('#modal').addEventListener('close',()=>{if(activeWidget!==null&&window.turnstile){window.turnstile.remove(activeWidget);activeWidget=null;}});
function modal(title,body){$('#modal-body').innerHTML=`<h2 id="modal-title">${esc(title)}</h2>${body}`;$('#modal').showModal();}
const button=(label,action,kind='')=>`<button class="btn ${kind}" data-action="${action}">${label}</button>`;
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;}
const initialHome=$('#main').innerHTML;
function home(){return initialHome.replace('<!--DRAFT-->',state.index>0&&!state.complete?`<div class="notice row"><span>${state.index}問まで回答しています。</span>${button('続きから','resume')}</div>`:'')+$('#home-ad').innerHTML+(receipt?`<details class="quiet-tools"><summary>調査への協力の控え</summary><div class="actions">${button('協力を取り消す','withdraw')}${button('控えを保存','backup')}</div></details>`:'');}

function start(mode){modal(mode===18?'18問で、好きの手がかりを。':'32問で、場面ごとの好みを。',`<p>成人同士で、互いに合意した関係を思い浮かべてください。経験がなくても、今の気持ちで答えられます。</p><p>想像で惹かれることと、実際に望むことは別々に聞きます。答えにくい問いは飛ばせます。</p>${state.complete?'<p class="muted">今の回答を作り直します。タグは引き継ぎます。</p>':''}<label class="check"><input type="checkbox" id="adult-check"><span>18歳以上です。</span></label><div class="actions">${button('始める','confirm-start','primary')}${button('戻る','close','plain')}</div>`);$('#modal').dataset.mode=mode;}
function quiz(){const ids=questionIds(state.mode,state.instrument),q=(state.instrument===INSTRUMENT?QUESTIONS:PREVIOUS_QUESTIONS)[ids[state.index]],labels=['当てはまらない','あまり当てはまらない','どちらともいえない','やや当てはまる','当てはまる'];return `<section class="quiz"><div class="quiz-top"><span>${state.index+1} / ${ids.length}問</span><button class="text-btn" data-action="pause">中断する</button></div><progress value="${state.index+1}" max="${ids.length}" aria-label="質問の進み具合"></progress><p class="eyebrow">${esc(q.context||'以前の質問')}</p><h1 id="question-title">${esc(q.text)}</h1><fieldset class="choices"><legend class="muted">今の気持ちに近いものを一つ</legend>${labels.map((label,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" ${state.answers[q.id]===i?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><div class="actions quiz-nav"><button class="btn plain" data-action="previous" ${state.index===0?'disabled':''}>戻る</button><button class="text-btn" data-action="skip">答えずに進む</button><button class="btn primary" data-action="next" ${state.answers[q.id]===null?'disabled':''}>${state.index===ids.length-1?'カルテを見る':'次へ　→'}</button></div></section>`;}
function advance(skip=false){const id=questionIds(state.mode,state.instrument)[state.index];if(skip)state.answers[id]=null;if(!skip&&state.answers[id]===null)return;if(state.index<state.mode-1){state.index++;persist();render();}else{state.complete=true;persist();navigate('profile');}}
const activeInstrument=()=>shared?shared.instrument:state.instrument;
const ownDimensions=()=>reflect(state.answers,state.instrument);
const shareOptions=(includeFantasy=false)=>({instrument:activeInstrument(),layers:includeFantasy?(shared?shared.layers:roleLayers(state.answers)):null});
const dimText=d=>activeInstrument()!==INSTRUMENT?`${d.description}について、以前の回答では「${d.level}」と表れています。`:d.n<2?'まだ手がかりは少なめ。わからないままでも大丈夫。':d.id==='care'?(d.mean>=3?'希望や余韻を、言葉にして伝え合いたい気持ちが表れています。':'言葉の量や伝え方は、相手と探していけます。') :d.mean>=3?`${d.description}に、心が動く答えが表れています。`:d.mean<=1?`${d.description}は、今はあまり惹かれないかもしれません。`:`${d.description}は、場面によって気持ちが変わりそう。`;
function detailRow(title,description,indices,dims){const layers=shared?shared.layers:activeInstrument()===INSTRUMENT?roleLayers(state.answers):null;return `<details class="disclosure"><summary><strong>${title}</strong><span>${phrase(description)}</span><span class="more">詳しく見る ›</span></summary><div class="detail-body dim-grid">${indices.map(i=>`<div class="dimension"><h3>${esc(dims[i].label)}</h3><p>${esc(dimText(dims[i]))}</p><span class="level">${esc(dims[i].level)}</span>${i<2&&activeInstrument()===INSTRUMENT?`<p class="layer-context">実際の希望について</p>${layers?`<p>想像の中では：${levelOf(layers[i*2].mean)}${layers[i*2].n===1?'（一つの答えから）':''}</p>`:'<p>想像の中の好みは、共有されていません。</p>'}`:''}${i===7?'<p>どの答えでも、相手の同意を確かめることは同じです。</p>':''}</div>`).join('')}</div></details>`;}
function discoveries(dims){const instrument=activeInstrument(),layers=shared?shared.layers:roleLayers(state.answers),description=describeProfile(dims,{layers,instrument});return `<section class="discoveries" aria-label="今回見つけた手がかり">${description.insights.map(insight=>`<article class="discovery"><h2>${esc(insight.title)}</h2><p>${esc(insight.text)}</p>${!shared?`<details class="answer-evidence"><summary>この言葉につながった回答</summary>${insight.ids.filter(id=>state.answers[id]!==null).slice(0,3).map(id=>`<p>${esc((instrument===INSTRUMENT?QUESTIONS:PREVIOUS_QUESTIONS)[id].text)}<br><strong>${['当てはまらない','あまり当てはまらない','どちらともいえない','やや当てはまる','当てはまる'][state.answers[id]]}</strong></p>`).join('')}</details>`:''}</article>`).join('')}<div class="conversation-prompt"><p class="eyebrow">${shared?'相手と話すきっかけに':'自分に聞くなら、相手と話すなら'}</p><p>${esc(description.prompt)}</p></div></section>`;}
function tagEditor(){const tags=shared?shared.tags:state.tags,ideas=describeProfile(shared?shared.dims:ownDimensions(),{instrument:activeInstrument()}).suggestions.filter(label=>!tags.some(t=>t.label===label));return `<section class="panel tag-panel"><div class="row"><h2>${shared?'共有された言葉':'<span class="phrase">好きなことを、</span><span class="phrase">あなたの言葉で。</span>'}</h2>${!shared?'<button class="text-btn" data-action="organize">整理する</button>':''}</div><p class="muted">${shared?'本人が選んで共有した、好きなことや避けたいこと。':'惹かれること、大切にしたいこと、今は避けたいこと。'}</p>${!shared?`<form id="tag-form" class="tag-form"><label class="sr-only" for="tag-input">タグを追加</label><input id="tag-input" maxlength="32" placeholder="例：落ち着く声、ギャップ" autocomplete="off"><label class="sr-only" for="tag-kind">タグの種類</label><select id="tag-kind"><option value="like">好き・大切</option><option value="boundary">今は避けたい</option></select><button class="btn primary">追加</button></form>${ideas.length?`<div class="tag-ideas"><p class="muted">しっくりきた言葉だけ、選んで追加</p><div class="tags">${ideas.map(label=>`<button class="tag" data-suggest-tag="${esc(label)}">＋ ${esc(label)}</button>`).join('')}</div></div>`:''}`:''}<div class="tag-groups">${tags.length?'':'<p class="tag-empty">まだ白紙です。ひとつ、好きな言葉を書いてみよう。</p>'}${Object.entries(GROUPS).filter(([id])=>tags.some(t=>t.group===id)).map(([id,label])=>`<section class="tag-group"><h3>${label}</h3><div class="tags">${tags.map((t,i)=>t.group===id?shared?`<span class="tag ${t.kind}">${t.kind==='boundary'?'避けたい：':''}${esc(t.label)}</span>`:`<button class="tag ${t.kind}" data-tag="${i}" aria-label="${esc(t.label)}を編集">${t.kind==='boundary'?'避けたい：':''}${esc(t.label)} <span aria-hidden="true">·</span></button>`:'').join('')||'<span class="tag-empty">まだありません</span>'}</div></section>`).join('')}</div>${!shared?`<div class="row"><small>${tags.length} / 24タグ · タップして編集できます</small>${undoTags?'<button class="text-btn" data-action="undo-tags">直前の整理を戻す</button>':''}</div>`:''}</section>`;}
function profile(){if(!state.complete&&!sample&&!shared)return `<section class="hero"><h1>まだ、白紙のカルテです。</h1><p>18問から、あなたの「好き」の手がかりを見つけよう。</p><div class="actions">${button('18問ではじめる','start18','primary')}${button('見本を見る','sample','plain')}</div></section>`;
 const dims=shared?shared.dims:ownDimensions(),description=describeProfile(dims,{layers:shared?shared.layers:roleLayers(state.answers),instrument:activeInstrument()});return `<div class="profile-heading"><p class="eyebrow">${shared?'共有されたカルテ':sample?'カルテの見本':'今回の「好き」の見出し'}</p><h1>${phrase(description.title)}</h1><p>${esc(description.summary)}</p></div>${activeInstrument()!==INSTRUMENT?`<div class="notice"><p>以前の質問で作ったカルテです。新しい質問でも、タグを引き継いで振り返れます。</p>${!shared?button('新しい18問に答える','start18','plain'):''}</div>`:''}${discoveries(dims)}${detailRow('誘う・委ねる・伝え合う','親密な時間の役回りと、言葉の好み。',[0,1,7],dims)}${detailRow('心が動く瞬間','ギャップ、声、まだ知らない一面。',[4,5,6],dims)}${detailRow('心地よい距離感','近くにいることと、自分の余白。',[2,3],dims)}${!shared&&state.mode===18&&activeInstrument()===INSTRUMENT?'<p class="result-note">18問で見つけた手がかりです。飛ばした問いや、この中にない好みは、タグで書き足せます。</p>':''}${tagEditor()}<div class="actions">${button(shared?(state.complete?'自分のカルテと比べる　→':'自分も答えて比べる　→'):'ふたりの好みを比べる　→','compare','primary')}${button('共有内容を確認　→','share')}</div><p class="result-note"><a href="/evidence/">このカルテで分かること・分からないこと</a></p>${$('#result-ad').innerHTML}
 ${!sample&&!shared?`<details class="quiet-tools"><summary>保存・見直し・調査への協力</summary><div class="actions" style="margin:20px 0">${button('データを保存','backup')}${button('回答を見直す','review')}${button('このカルテを消す','reset','plain')}${localStorage.getItem(PREVIOUS_KEY)?button('前のカルテを保存','backup-previous','plain'):''}</div><h2>よりよいカルテを、一緒につくる</h2><p class="muted">希望する方は、数値の回答を調査に提供できます。自由に書いたタグや名前は送りません。<a href="/privacy/#research">提供する情報と取り消しについて</a></p>${receipt?'<p>協力の控えがあります。</p>'+(receipt.pending?button('提供をもう一度試す','research'):'')+button('調査への協力を取り消す','withdraw'):SITEKEY&&activeInstrument()===INSTRUMENT?button('協力内容を確認する','research'):'<p class="muted">新しい質問に答えると、調査に協力できます。</p>'}<p><button class="text-btn" data-action="reference">参加者の参考値を見る</button></p><div id="reference-result" role="status"></div></details>`:''}`;}
function editTag(index){const t=state.tags[index];if(!t)return;modal('タグを整える',`<label class="label" for="edit-label">あなたの言葉</label><input id="edit-label" maxlength="32" value="${esc(t.label)}"><label class="label" for="edit-group">置く場所</label><select id="edit-group">${Object.entries(GROUPS).map(([id,label])=>`<option value="${id}" ${t.group===id?'selected':''}>${label}</option>`).join('')}</select><label class="label" for="edit-kind">種類</label><select id="edit-kind"><option value="like" ${t.kind==='like'?'selected':''}>好き・大切</option><option value="boundary" ${t.kind==='boundary'?'selected':''}>今は避けたい</option></select><div class="actions" style="margin-top:24px">${button('保存する','save-tag','primary')}${button('削除する','delete-tag','plain')}</div>`);$('#modal').dataset.tag=index;}
function compare(){const own=compareCode||(state.complete||sample||shared?encodeProfile(shared?shared.dims:ownDimensions(),[],shareOptions()):'');return `<p class="eyebrow">ふたりでも、みんなでも</p><h1>違いを知ると、話せることが増える。</h1><p class="muted">相手もカルテを作り、「共有内容を確認」からURLを受け取ってください。相性の合否を決めず、話すきっかけを見つけます。</p>${!own?`<div class="notice"><p>先に自分のカルテを作ると、ここで比べられます。</p>${button('18問ではじめる','start18','primary')}</div>`:''}<section class="panel">${own?'<p>自分のカルテを使って比べます。</p><details><summary>別のカルテを使う</summary>':''}<label class="label" for="own-code">自分の共有URLかコード</label><input id="own-code" style="width:100%" placeholder="共有URL または H3.…" value="${esc(own)}">${own?'</details>':''}<label class="label" for="partner-codes">相手から受け取ったURLかコード</label><textarea id="partner-codes" rows="3" placeholder="ここに貼り付ける">${esc(pendingPartnerCode)}</textarea><p class="muted">最大3人。複数なら、1人ずつ改行してください。</p><div class="actions" style="margin-top:22px">${button('比べてみる','run-compare','primary')}<a class="btn plain" href="/legacy/#pair">旧版のタイプコードを使う</a></div><p id="compare-error" class="error" role="alert"></p></section><div id="comparison" tabindex="-1"></div>`;}
function readCode(text){const value=text.trim();if(/^H[23]\./.test(value))return decodeProfile(value);try{const u=new URL(value);return decodeProfile(new URLSearchParams(u.hash.slice(1)).get('share'));}catch{throw Error('共有コードか、受け取った共有URLを確認してください。');}}
function runCompare(){try{const mine=readCode($('#own-code').value),lines=$('#partner-codes').value.split(/\n/).filter(s=>s.trim());if(lines.length<1||lines.length>3)throw Error('相手のカルテを1〜3人分、1人ずつ改行して入れてください。');const partners=lines.map(readCode),all=[mine,...partners];let content='';for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++){const pairs=compareProfiles(all[i].dims,all[j].dims,{sameInstrument:all[i].instrument===all[j].instrument,instrument:all[i].instrument});content+=`<section class="panel"><h2>${i===0?'あなた':'相手'+i} × 相手${j}</h2><p class="muted">${all[i].instrument===all[j].instrument?'似ていても違っていても、今の希望を確かめながら。':'答えた質問が違うため、好みの近さは比べません。話題のヒントとして読んでください。'}</p>${pairs.map(d=>`<details class="comparison-row"><summary>${esc(d.label)} <span class="badge">${d.unknown?'まだわからない':d.similar?'近いところがありそう':'話してみたい違い'}</span></summary><p>${esc(d.prompt)}</p></details>`).join('')}${all[i].tags.length||all[j].tags.length?`<h3 style="margin-top:24px">共有されたタグ</h3><p>${all[i].tags.concat(all[j].tags).map(t=>esc((t.kind==='boundary'?'避けたい：':'')+t.label)).join(' ／ ')}</p>`:''}</section>`;}$('#comparison').innerHTML=content;$('#compare-error').textContent='';$('#comparison').scrollIntoView({block:'start'});$('#comparison').focus({preventScroll:true});}catch(e){$('#compare-error').textContent=e.message;}}
function share(){const dims=shared?shared.dims:ownDimensions(),tags=shared?shared.tags:state.tags;modal('見せたいことだけ、選ぼう。',`<p>好みの傾向を共有します。タグは選んだものだけ。URLを知る人は内容を読んだり、保存・転送したりできます。</p>${activeInstrument()===INSTRUMENT?'<label class="check"><input type="checkbox" id="share-fantasy"><span>想像の中の「主導・委ね」の好みも含める</span></label>':''}<div id="share-tags">${tags.map((t,i)=>`<label class="check"><input type="checkbox" data-share-tag="${i}"><span>${t.kind==='boundary'?'避けたい：':''}${esc(t.label)}</span></label>`).join('')}</div><label class="label" for="share-output">共有URL</label><textarea id="share-output" class="share-code" readonly></textarea><div class="actions" style="margin:20px 0">${button('URLをコピー','copy-share','primary')}${button('コードをコピー','copy-code')}${button('画像を保存','save-image')}</div><canvas id="share-canvas" width="1200" height="630" aria-label="選んだ内容の共有カード"></canvas>`);const update=()=>{const selected=[...document.querySelectorAll('[data-share-tag]:checked')].map(e=>tags[Number(e.dataset.shareTag)]),code=encodeProfile(dims,selected,shareOptions(!!$('#share-fantasy')?.checked));$('#share-output').value=location.origin+'/#share='+code;$('#share-output').dataset.code=code;drawCard(dims,selected,$('#share-fantasy')?.checked?(shared?shared.layers:roleLayers(state.answers)):null);};$('#share-tags').addEventListener('change',update);$('#share-fantasy')?.addEventListener('change',update);update();}
function drawCard(dims,tags,layers=null){const c=$('#share-canvas'),ctx=c.getContext('2d');ctx.fillStyle='#13111b';ctx.fillRect(0,0,1200,630);ctx.fillStyle='#b99ae6';ctx.font='bold 30px sans-serif';ctx.fillText('HEKI16　好きの輪郭を、自分の言葉で。',64,72);ctx.fillStyle='#f4f0fa';ctx.font='bold 44px sans-serif';ctx.fillText(describeProfile(dims,{instrument:activeInstrument()}).title,64,152);ctx.font='24px sans-serif';const fit=(s,w)=>{while(ctx.measureText(s).width>w)s=s.slice(0,-2)+'…';return s;};dims.forEach((d,i)=>{const x=64+(i%2)*560,y=220+Math.floor(i/2)*66;ctx.fillStyle='#f4f0fa';ctx.fillText(activeInstrument()===INSTRUMENT&&i<2?(i===0?'主導（実際）':'委ね（実際）'):d.label,x,y);ctx.fillStyle='#b99ae6';ctx.fillText(d.n<2?'まだわからない':levelOf(d.mean),x+240,y);});ctx.fillStyle='#bcb4ca';ctx.font='22px sans-serif';if(layers)ctx.fillText(`想像の中では：主導 ${levelOf(layers[0].mean)} ／ 委ね ${levelOf(layers[2].mean)}`,64,468);ctx.fillText(fit(tags.map(t=>(t.kind==='boundary'?'避けたい：':'#')+t.label).join('　'),1070),64,520);ctx.font='20px sans-serif';ctx.fillText('heki16-pro.aiyume.workers.dev　·　好みは変わってもいい。',64,584);}
async function copy(value){try{await navigator.clipboard.writeText(value);say('コピーしました。');}catch{const output=$('#share-output');output.value=value;output.focus();output.select();say('この欄を選択してコピーしてください。');}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function research(){if(!SITEKEY||sample||shared||!state.complete||state.instrument!==INSTRUMENT)return;modal('調査への協力について',`<p>送るものは、今回の数値の回答、回答したコース、タグの分類ごとの個数です。名前・自由に書いたタグ・連絡先は送りません。</p><p>回答は180日を目安に自動削除し、質問の見直しと参加者全体の参考値に使います。広告の選別には使いません。取り消すと回答を削除します。</p><label class="check"><input id="research-consent" type="checkbox"><span>18歳以上で、<a href="/privacy/#research" target="_blank" rel="noopener">提供する情報と取り消し方法</a>を確認し、協力に同意します。</span></label><div id="turnstile-box"></div><p id="research-error" class="error" role="alert"></p>${button('同意して回答を提供する','submit-research','primary')}`);$('#modal [data-action="submit-research"]').disabled=true;$('#research-consent').addEventListener('change',async e=>{if(!e.target.checked){$('#modal [data-action="submit-research"]').disabled=true;return;}try{if(!window.turnstile)await new Promise((resolve,reject)=>{const existing=$('#turnstile-script');if(existing){existing.remove();}const script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=reject;document.head.append(script);});if($('#turnstile-box').dataset.loaded&&$('#turnstile-box').dataset.token){$('#modal [data-action="submit-research"]').disabled=false;}if(!$('#turnstile-box').dataset.loaded){$('#turnstile-box').dataset.loaded='true';activeWidget=window.turnstile.render('#turnstile-box',{sitekey:SITEKEY,action:'research',theme:'dark',size:'compact',callback:token=>{if(!$('#research-consent'))return;$('#turnstile-box').dataset.token=token;$('#research-error').textContent='';$('#modal [data-action="submit-research"]').disabled=!$('#research-consent').checked;},'expired-callback':()=>{if($('#turnstile-box'))$('#turnstile-box').dataset.token='';if($('#modal [data-action="submit-research"]'))$('#modal [data-action="submit-research"]').disabled=true;}});}}catch{$('#research-error').textContent='確認を読み込めませんでした。時間をおいてお試しください。';}});}
async function submitResearch(){const submit=$('#modal [data-action="submit-research"]');if(!$('#research-consent')?.checked||!$('#turnstile-box')?.dataset.token)return;submit.disabled=true;try{if(!receipt){const raw=crypto.getRandomValues(new Uint8Array(32));receipt={id:crypto.randomUUID(),deletionToken:btoa(String.fromCharCode(...raw)).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_'),pending:true};localStorage.setItem(RECEIPT,JSON.stringify(receipt));}const r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...receipt,pending:undefined,instrument:INSTRUMENT,consent:CONSENT,adult:true,mode:state.mode,answers:state.answers,groups:Object.keys(GROUPS).map(g=>state.tags.filter(t=>t.group===g).length),token:$('#turnstile-box').dataset.token})});if(!r.ok)throw Error('現在、回答を受け付けられません。時間をおいてお試しください。');receipt={id:receipt.id,deletionToken:receipt.deletionToken,accepted:true};localStorage.setItem(RECEIPT,JSON.stringify(receipt));close();say('ご協力ありがとうございます。いつでも取り消せます。');render();}catch(e){$('#research-error').textContent=e.message;$('#turnstile-box').dataset.token='';submit.disabled=true;if(activeWidget!==null&&window.turnstile)window.turnstile.reset(activeWidget);}}
async function withdraw(){const r=await fetch('/api/research/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:receipt.id,deletionToken:receipt.deletionToken})});if(!r.ok){say('取り消せませんでした。控えを残して、時間をおいてお試しください。');return;}localStorage.removeItem(RECEIPT);receipt=null;close();render();say('調査への協力を取り消しました。');}
async function reference(){const target=$('#reference-result');target.textContent='確認しています…';try{const r=await fetch('/api/reference');if(!r.ok)throw Error();const p=await r.json();target.textContent=p.ready?`${p.responsesAtLeast}件以上の協力回答による参考値です。同じ人の複数回答を含む可能性があり、一般の人全体を表すものではありません。`: '参考値は準備中です。今の自分の気持ちを大切にしてください。';}catch{target.textContent='今は確認できません。時間をおいてお試しください。';}}
function withdrawal(){return `<h1>調査への協力を取り消す</h1><p class="muted">保存した控えの内容を、下の欄へ貼り付けてください。取り消しの照合に必要な情報だけを送ります。</p><label class="label" for="receipt-input">控えの内容</label><textarea id="receipt-input" rows="8" maxlength="65536" placeholder="保存したJSONの内容"></textarea><p id="receipt-error" role="alert" class="error"></p>${button('控えを確認する','read-receipt','primary')}`;}
function render(preserve=false){const scroll=window.scrollY,openDetails=preserve?[...document.querySelectorAll('main details')].map(el=>el.open):[],focusId=document.activeElement?.id;const route=location.hash.slice(1)||'home';if(route.startsWith('share=')){try{shared=readCode(location.href);sample=false;}catch(e){shared=null;say(e.message);}}else shared=null;document.querySelectorAll('.site-header nav a').forEach(a=>{if(a.hash==='#'+(shared?'profile':route))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=route==='withdraw'?withdrawal():route==='quiz'?quiz():route==='profile'||shared?profile():route==='compare'?compare():home();if(preserve){[...document.querySelectorAll('main details')].forEach((el,i)=>el.open=!!openDetails[i]);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});window.scrollTo(0,scroll);}else{$('#main').focus({preventScroll:true});window.scrollTo(0,0);}}
document.addEventListener('change',e=>{if(e.target.name==='answer'){state.answers[questionIds(state.mode,state.instrument)[state.index]]=Number(e.target.value);persist();$('[data-action="next"]').disabled=false;}});
document.addEventListener('submit',e=>{if(e.target.id!=='tag-form')return;e.preventDefault();const label=normalizeLabel($('#tag-input').value);if(!label){say('タグの言葉を入力してください。');return;}if(state.tags.length>=24){say('タグは24個まで。今あるタグを編集できます。');return;}undoTags=structuredClone(state.tags);state.tags=organizeTags([...state.tags,{label,kind:$('#tag-kind').value}],state.learned);persist();render(true);$('#tag-input').focus({preventScroll:true});say('タグを追加して整理しました。');});
document.addEventListener('click',async e=>{if(e.target.closest('a[href="#main"]')){e.preventDefault();$('#main').focus();return;}const suggested=e.target.closest('button[data-suggest-tag]');if(suggested){if(state.tags.length>=24){say('タグは24個まで。今あるタグを編集できます。');return;}undoTags=structuredClone(state.tags);state.tags=organizeTags([...state.tags,{label:suggested.dataset.suggestTag,kind:'like'}],state.learned);persist();render(true);say('選んだ言葉を追加しました。');return;}const tag=e.target.closest('button[data-tag]');if(tag){editTag(Number(tag.dataset.tag));return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 try{switch(action){case 'start32':case 'start18':start(action==='start18'?18:32);break;case 'confirm-start':if(!$('#adult-check').checked){say('18歳以上の方を対象としています。');return;}const mode=Number($('#modal').dataset.mode);state={...empty(),tags:state.tags,learned:state.learned,mode,adult:true};sample=false;shared=null;persist();close();navigate('quiz');break;
 case 'resume':sample=false;navigate('quiz');break;case 'sample':sample=true;state.sampleBackup=structuredClone(state);state={...empty(),complete:true,answers:Array.from({length:32},(_,i)=>[3,3,4,3,2,4,2,4][i%8]),tags:organizeTags(['落ち着く声','静かな場所','ふたりの時間','自分のペース','安心感','思いやり']),sampleBackup:state.sampleBackup};navigate('profile');break;
 case 'pause':persist();navigate('home');break;case 'next':advance();break;case 'skip':advance(true);break;case 'previous':state.index=Math.max(0,state.index-1);persist();render();break;case 'review':state.index=0;navigate('quiz');break;case 'compare':if(shared){const inputs=comparisonInputs(state.complete?{dims:ownDimensions(),instrument:state.instrument}:null,shared);compareCode=inputs.own;pendingPartnerCode=inputs.partner;}else compareCode=encodeProfile(ownDimensions(),[],{instrument:state.instrument});navigate('compare');break;case 'run-compare':runCompare();break;case 'share':share();break;case 'copy-share':await copy($('#share-output').value);break;case 'copy-code':await copy($('#share-output').dataset.code);break;case 'save-image':$('#share-canvas').toBlob(b=>download(b,'heki16-card.png'),'image/png');break;
 case 'organize':undoTags=structuredClone(state.tags);state.tags=organizeTags(state.tags,state.learned);persist();render(true);say('タグを整理しました。');break;case 'undo-tags':if(undoTags){state.tags=undoTags;undoTags=null;persist();render(true);say('直前のタグに戻しました。');}break;
 case 'save-tag':{const index=Number($('#modal').dataset.tag),label=normalizeLabel($('#edit-label').value);if(!label){say('タグの言葉を入力してください。');return;}undoTags=structuredClone(state.tags);const group=$('#edit-group').value;state.learned[label]=group;state.tags[index]={label,group,kind:$('#edit-kind').value,manual:true};state.tags=organizeTags(state.tags,state.learned);persist();close();render(true);say('タグを保存しました。');break;}
 case 'delete-tag':undoTags=structuredClone(state.tags);state.tags.splice(Number($('#modal').dataset.tag),1);persist();close();render(true);say('タグを削除しました。元に戻せます。');break;
 case 'backup-previous':download(new Blob([JSON.stringify({state:JSON.parse(localStorage.getItem(PREVIOUS_KEY))},null,2)],{type:'application/json'}),'heki16-previous-private-backup.json');break;
 case 'backup':download(new Blob([JSON.stringify({state,receipt},null,2)],{type:'application/json'}),'heki16-private-backup.json');break;
 case 'reset':modal('このカルテを消しますか？',`<p>このブラウザーの回答とタグを消します。調査へ提供した回答の取り消しは、別に行えます。</p><div class="actions">${button('カルテを消す','confirm-reset')}${button('戻る','close','plain')}</div>`);break;case 'confirm-reset':state=empty();sample=false;shared=null;persist();close();navigate('home');break;
 case 'read-receipt':{try{const r=JSON.parse($('#receipt-input').value).receipt;if(!r||!/^[-a-f0-9]{36}$/i.test(r.id)||!/^[A-Za-z0-9_-]{43}$/.test(r.deletionToken))throw Error();receipt={id:r.id,deletionToken:r.deletionToken};modal('この控えの協力を取り消しますか？',`<p>提供した回答を削除します。手元のカルテは残ります。</p><div class="actions">${button('協力を取り消す','confirm-withdraw')}${button('戻る','close','plain')}</div>`);}catch{$('#receipt-error').textContent='控えの内容を確認してください。';}break;}case 'research':research();break;case 'submit-research':await submitResearch();break;case 'withdraw':modal('調査への協力を取り消しますか？',`<p>提供した回答を削除します。手元のカルテは残ります。</p><div class="actions">${button('協力を取り消す','confirm-withdraw')}${button('戻る','close','plain')}</div>`);break;case 'confirm-withdraw':await withdraw();break;case 'reference':await reference();break;case 'close':close();break;}}
 catch{say('操作を完了できませんでした。もう一度お試しください。');}
});
window.addEventListener('hashchange',()=>{if(sample&&!['#profile','#compare'].includes(location.hash)){state=state.sampleBackup||empty();sample=false;}render();});
if(/^#(?:partner|group|pair)=/.test(location.hash))location.replace('/legacy/'+location.hash);else render();
